import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define MAX_COUT 128

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bs,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int CoutPerGroup, int CinPerGroup,
    int Kd, int Kh, int Kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw,
    int Dout, int Hout, int Wout)
{
  const int n = blockIdx.y;
  const int p = blockIdx.x * blockDim.x + threadIdx.x;
  const int P_total = Dout * Hout * Wout;
  const bool valid_p = (p < P_total);

  int od = 0, oh = 0, ow = 0;
  if (valid_p) {
    const int hw = Hout * Wout;
    od = p / hw;
    int rem = p - od * hw;
    oh = rem / Wout;
    ow = rem - oh * Wout;
  }

  // Shared memory holds one (kd,kh,kw) weight slice: [Cin, CoutPerGroup]
  extern __shared__ float sW_raw[];
  auto sW = make_tensor(make_smem_ptr(sW_raw),
                         make_shape(Cin, CoutPerGroup),
                         make_stride(CoutPerGroup, 1));

  float acc[MAX_COUT];
  #pragma unroll
  for (int co = 0; co < MAX_COUT; ++co) acc[co] = 0.0f;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * Cin * D * H * Win),
      make_shape(Cin, D, H, Win),
      make_stride((int64_t)D * H * Win, (int64_t)H * Win, (int64_t)Win, (int64_t)1));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, CoutPerGroup, Kd, Kh, Kw),
      make_stride((int64_t)CoutPerGroup * Kd * Kh * Kw,
                  (int64_t)Kd * Kh * Kw,
                  (int64_t)Kh * Kw,
                  (int64_t)Kw,
                  (int64_t)1));

  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const int total_w = Cin * CoutPerGroup;

  for (int kd = 0; kd < Kd; ++kd) {
    int id_num = od + pd - kd;
    bool id_ok = (id_num % sd == 0);
    int id = id_ok ? (id_num / sd) : -1;
    id_ok = id_ok && (id >= 0 && id < D);

    for (int kh = 0; kh < Kh; ++kh) {
      int ih_num = oh + ph - kh;
      bool ih_ok = (ih_num % sh == 0);
      int ih = ih_ok ? (ih_num / sh) : -1;
      ih_ok = ih_ok && (ih >= 0 && ih < H);

      for (int kw = 0; kw < Kw; ++kw) {
        int iw_num = ow + pw - kw;
        bool iw_ok = (iw_num % sw == 0);
        int iw = iw_ok ? (iw_num / sw) : -1;
        iw_ok = iw_ok && (iw >= 0 && iw < Win);

        // Cooperative load of weight slice for (kd,kh,kw)
        for (int idx = tid; idx < total_w; idx += nthreads) {
          int ci = idx / CoutPerGroup;
          int col = idx % CoutPerGroup;
          sW(ci, col) = (float)mW(ci, col, kd, kh, kw);
        }
        __syncthreads();

        const bool valid = valid_p && id_ok && ih_ok && iw_ok;
        if (valid) {
          for (int ci = 0; ci < Cin; ++ci) {
            float xval = (float)mX(ci, id, ih, iw);
            int g = ci / CinPerGroup;
            int co_base = g * CoutPerGroup;
            #pragma unroll 4
            for (int col = 0; col < CoutPerGroup; ++col) {
              acc[co_base + col] += xval * sW(ci, col);
            }
          }
        }
        __syncthreads();
      }
    }
  }

  if (valid_p) {
    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * Cout * Dout * Hout * Wout),
        make_shape(Cout, Dout, Hout, Wout),
        make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

    for (int co = 0; co < Cout; ++co) {
      float val = acc[co];
      if (Bs != nullptr) val += (float)Bs[co];
      mY(co, od, oh, ow) = (T)val;
    }
  }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    int64_t groups)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N,Cin,D,H,W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, Kd, Kh, Kw]");
  TORCH_CHECK(stride.size() == 3 && padding.size() == 3 && output_padding.size() == 3,
              "stride/padding/output_padding must have 3 elements");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D = x_c.size(2);
  int64_t H = x_c.size(3);
  int64_t Win = x_c.size(4);

  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal Cin");
  int64_t CoutPerGroup = w_c.size(1);
  int64_t Kd = w_c.size(2);
  int64_t Kh = w_c.size(3);
  int64_t Kw = w_c.size(4);

  int64_t g = groups;
  TORCH_CHECK(Cin % g == 0, "Cin must be divisible by groups");
  int64_t CinPerGroup = Cin / g;
  int64_t Cout = CoutPerGroup * g;
  TORCH_CHECK(Cout <= MAX_COUT, "Cout exceeds MAX_COUT limit in kernel");

  int64_t sd = stride[0], sh = stride[1], sw = stride[2];
  int64_t pd = padding[0], ph = padding[1], pw = padding[2];
  int64_t opd = output_padding[0], oph = output_padding[1], opw = output_padding[2];

  int64_t Dout = (D - 1) * sd - 2 * pd + Kd + opd;
  int64_t Hout = (H - 1) * sh - 2 * ph + Kh + oph;
  int64_t Wout = (Win - 1) * sw - 2 * pw + Kw + opw;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  const int Threads = 256;
  int64_t P_total = Dout * Hout * Wout;

  dim3 block(Threads);
  dim3 grid((unsigned)((P_total + Threads - 1) / Threads), (unsigned)N, 1);

  size_t smem_bytes = (size_t)CinPerGroup_dummy_unused = 0; // placeholder removed below
  smem_bytes = (size_t)Cin * (size_t)CoutPerGroup * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)CoutPerGroup, (int)CinPerGroup,
      (int)Kd, (int)Kh, (int)Kw,
      (int)sd, (int)sh, (int)sw,
      (int)pd, (int)ph, (int)pw,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

# fix the accidental typo line introduced above (dummy placeholder) by patching source text safely
cuda_src = cuda_src.replace(
    "size_t smem_bytes = (size_t)CinPerGroup_dummy_unused = 0; // placeholder removed below\n  smem_bytes = (size_t)Cin * (size_t)CoutPerGroup * sizeof(float);",
    "size_t smem_bytes = (size_t)Cin * (size_t)CoutPerGroup * sizeof(float);"
)

conv_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with asymmetric input/kernel sizes, implemented
    with a single custom CUDA kernel using CuTe tensors for tiled cooperative
    computation (shared-memory weight caching across the kernel volume loop).
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(int(k) for k in kernel_size)
        self.stride = tuple(int(s) for s in stride)
        self.padding = tuple(int(p) for p in padding)
        self.output_padding = tuple(int(p) for p in output_padding)
        self.groups = int(groups)

        Cin = self.in_channels
        Cout = self.out_channels
        Kd, Kh, Kw = self.kernel_size

        assert Cin % self.groups == 0
        assert Cout % self.groups == 0
        CoutPerGroup = Cout // self.groups

        # PyTorch ConvTranspose3d weight layout: [Cin, Cout/groups, Kd, Kh, Kw]
        self.weight = nn.Parameter(torch.empty(Cin, CoutPerGroup, Kd, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            Cin = self.in_channels
            Kd, Kh, Kw = self.kernel_size
            fan_in = Cin * Kd * Kh * Kw / max(self.groups, 1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            list(self.stride),
            list(self.padding),
            list(self.output_padding),
            self.groups,
        )

