import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

MAX_COUT = 128
THREADS = 256

# ---------------------------------------------------------------------------
# Hand authored PTX implementing a transposed 3D convolution.
#
# Algorithm (mirrors the CuTe/CUDA reference kernel):
#   * one thread handles one output spatial location (od, oh, ow) for one
#     batch element n (grid.y == n, grid.x*block.x + tid == flattened p)
#   * a per-thread local accumulator (float[128], local memory) holds the
#     partial result for every output channel
#   * for every (kd, kh, kw) kernel offset, the whole block cooperatively
#     stages the corresponding weight slice W[:, :, kd, kh, kw] into shared
#     memory, then (if the corresponding input location is valid) every
#     thread accumulates over Cin input channels / CoutPerGroup output
#     channels using the staged weights
#   * finally the accumulator is written to the output tensor (with the
#     optional bias added)
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.extern .shared .align 4 .b8 sW[];

.visible .entry conv_transpose3d_kernel(
    .param .u64 X,
    .param .u64 W,
    .param .u64 Bs,
    .param .u64 Y,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 D,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 CoutPerGroup,
    .param .u32 CinPerGroup,
    .param .u32 Kd,
    .param .u32 Kh,
    .param .u32 Kw,
    .param .u32 sd,
    .param .u32 sh,
    .param .u32 sw,
    .param .u32 pd,
    .param .u32 ph,
    .param .u32 pw,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout
)
{
    .local .align 16 .b8 __local_depot0[512];
    .reg .b64 %SPL;
    .reg .b64 %rd<150>;
    .reg .b32 %r<160>;
    .reg .f32 %f<20>;
    .reg .pred %p<40>;

    mov.u64 %SPL, __local_depot0;

    ld.param.u64 %rd1, [X];
    ld.param.u64 %rd2, [W];
    ld.param.u64 %rd3, [Bs];
    ld.param.u64 %rd4, [Y];
