def validate_generated_code():
    """Compile the PTX module and make sure the entry point is present."""
    module = PtxModule(PTX_SOURCE)
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"entry point {_KERNEL_NAME} not found in PTX module"
    return True


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with asymmetric input/kernel sizes, implemented
    with a hand written PTX kernel launched through
    `cutegen.ptx_runtime.PtxModule`. The kernel mirrors the CuTe/CUDA
    reference: each thread computes one output spatial location for one
    batch element, cooperatively staging the per-(kd,kh,kw) weight slice into
    shared memory before accumulating over input channels.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(int(k) for k in kernel_size)
        self.stride = tuple(int(s) for s in stride)
        self.padding = tuple(int(p) for p in padding)
        self.output_padding = tuple(int(p) for p in output_padding)
        self.groups = int(groups)

        Cin = self.in_channels
        Cout = self.out_channels
        Kd, Kh, Kw = self.kernel_size

        assert Cin % self.groups == 0
        assert Cout % self.groups == 0
        CoutPerGroup = Cout // self.groups
        assert Cout <= MAX_COUT, "Cout exceeds MAX_COUT limit in kernel"

        # PyTorch ConvTranspose3d weight layout: [Cin, Cout/groups, Kd, Kh, Kw]
        self.weight = nn.Parameter(torch.empty(Cin, CoutPerGroup, Kd, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._module = None

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            Cin = self.in_channels
            Kd, Kh, Kw = self.kernel_size
            fan_in = Cin * Kd * Kh * Kw / max(self.groups, 1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def _get_module(self) -> PtxModule:
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be CUDA"
        x_c = x.contiguous().to(torch.float32)
        w_c = self.weight.contiguous().to(torch.float32)

        N, Cin, D, H, Win = x_c.shape
        CoutPerGroup = w_c.shape[1]
        Kd, Kh, Kw = w_c.shape[2], w_c.shape[3], w_c.shape[4]

        g = self.groups
        CinPerGroup = Cin // g
        Cout = CoutPerGroup * g

        sd, sh, sw = self.stride
        pd, ph, pw = self.padding
        opd, oph, opw = self.output_padding

        Dout = (D - 1) * sd - 2 * pd + Kd + opd
        Hout = (H - 1) * sh - 2 * ph + Kh + oph
        Wout = (Win - 1) * sw - 2 * pw + Kw + opw
        assert Dout > 0 and Hout > 0 and Wout > 0, "Invalid output size computed"

        if self.bias is not None:
            b_c = self.bias.contiguous().to(torch.float32)
            b_ptr = b_c.data_ptr()
        else:
            b_c = None
            b_ptr = 0

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=torch.float32)

        module = self._get_module()

        P_total = Dout * Hout * Wout
        grid_x = (P_total + THREADS - 1) // THREADS
        grid = (grid_x, N, 1)
        block = (THREADS, 1, 1)
        smem_bytes = Cin * CoutPerGroup * 4

        stream = torch.cuda.current_stream(x.device).cuda_stream

        module.launch(
            _KERNEL_NAME,
            grid=grid,
            block=block,
            shared_mem=smem_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(b_ptr),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(D), i32(H), i32(Win),
                i32(Cout), i32(CoutPerGroup), i32(CinPerGroup),
                i32(Kd), i32(Kh), i32(Kw),
                i32(sd), i32(sh), i32(sw),
                i32(pd), i32(ph), i32(pw),
                i32(Dout), i32(Hout), i32(Wout),
            ],
        )

        return y
